@pytest.fixture def analysis_scenario(session): teacher = add_teacher(session) course = Course(name="考情夹具", created_by=teacher.id) session.add(course) session.flush() questions = [ Question( course_id=course.id, created_by=teacher.id, type=QuestionType.SINGLE_CHOICE, content=f"原题{i}", reference_answer="A", score=Decimal("99.00"), status=QuestionStatus.APPROVED, knowledge_points=["当前题库标签"], ) for i in range(2) ] session.add_all(questions) session.flush() exam = Exam( course_id=course.id, created_by=teacher.id, title="固定分值考试", status=ExamStatus.PUBLISHED, ) exam.exam_question_links = [ ExamQuestion( question=q, order_index=i + 1, score=Decimal(score), base_score=Decimal("99.00"), published_knowledge_points=tags, ) for i, (q, score, tags) in enumerate( zip(questions, ["2.00", "3.00"], [["一次函数"], ["一次函数", "表达与计算"]]) ) ] session.add(exam) session.commit() students = [add_student(session, username=f"s{i}") for i in range(7)] session.add_all( ExamParticipant(exam_id=exam.id, student_id=student.id) for student in students ) submissions = [] for i, student in enumerate(students[:6]): sub = Submission( exam_id=exam.id, student_id=student.id, status=SubmissionStatus.DRAFT if i == 5 else SubmissionStatus.SUBMITTED, submitted_at=None if i == 5 else datetime.now(UTC), ) session.add(sub) session.flush() session.add_all( Answer( submission_id=sub.id, question_id=q.id, content="B", status=AnswerStatus.SUBMITTED, ) for q in questions ) submissions.append(sub) session.commit() > repository = DatabaseGradingRepository(session=session) ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E TypeError: DatabaseGradingRepository.__init__() got an unexpected keyword argument 'session'
